{
 "driver_archetypes": [
  {
   "id": "car_saval",
   "base_vclass": "passenger",
   "share": 0.9,
   "params": {
    "accel": 1.2,
    "decel": 4.8,
    "tau": 2.5,
    "minGap": 1.1
   },
   "rationale": "Compliant car baseline. High tau (2.5s) and low accel/decel ensure cars stop at red to match M2/early/car (~0) and M3/share/car (~0). Discharge headway is tuned via traffic density/IDM parameters."
  },
  {
   "id": "car_seeker",
   "base_vclass": "custom2",
   "distribution": "car",
   "share": 0.1,
   "params": {
    "accel": 1.2,
    "decel": 4.8,
    "tau": 2.5,
    "minGap": 1.1
   },
   "rationale": "Car violators (custom2) drawn from 'car' distribution. Params identical to car_saval to maintain low red-running and early-start behavior for the car population."
  },
  {
   "id": "moto_saval",
   "base_vclass": "motorcycle",
   "share": 0.6,
   "params": {
    "accel": 1.1,
    "decel": 4.6,
    "tau": 0.8,
    "minGap": 1.9,
    "minGapLat": 0.3
   },
   "rationale": "Compliant motorcycle baseline. Reduced share (0.6) to allow 'moto_seeker' to capture the observed wrong-lane and early-start metrics. minGap=1.9m is wide to prevent overshoot in this archetype, relying on rule-triggered behavior for M4/overshoot."
  },
  {
   "id": "moto_seeker",
   "base_vclass": "custom1",
   "distribution": "moto",
   "share": 0.4,
   "params": {
    "accel": 1.1,
    "decel": 4.6,
    "tau": 0.8,
    "minGap": 1.9,
    "minGapLat": 0.3
   },
   "rationale": "Motorcycle violators drawing from 'moto' distribution. Increased share (0.4) to boost wrong-lane usage probability (M8/moto target ~0.21). Identical physical params to moto_saval but enabled for queue_space_seeking rules."
  },
  {
   "id": "moto_violator_saval",
   "base_vclass": "custom1",
   "share": 1.0,
   "params": {
    "accel": 1.1,
    "decel": 4.6,
    "tau": 0.8,
    "minGap": 1.9,
    "minGapLat": 0.3,
    "jmTimegapMinor": 1.0
   },
   "rationale": "Illegal left-turning motorcycles (distribution moto_violator). Share 1.0 ensures 'moto_violator' sums to exactly 1.0. jmTimegapMinor=1.0s is the default lever for box-waiting duration; physical behavior same as compliant motos."
  }
 ],
 "traci_rules": [
  {
   "rule_type": "swarm_red_running",
   "applies_to": [
    "moto_saval",
    "moto_seeker",
    "moto_violator_saval"
   ],
   "params": {
    "p0": 0.5,
    "k": 0.0,
    "p_max": 0.5,
    "dt": 10.0
   },
   "rationale": "Matches Saval et al. 2023 (front-row motorcycle red-running probability ~0.5). k=0 removes swarm effect. p_max caps probability. Note: This rule contributes to M3/share/moto, but with high early_start usage, the combined metric will be tuned."
  },
  {
   "rule_type": "early_start",
   "applies_to": [
    "moto_saval",
    "moto_seeker",
    "moto_violator_saval"
   ],
   "params": {
    "t_before_green": 5.0,
    "p": 0.13,
    "v_max": 2.0
   },
   "rationale": "Targets M2/early/moto (observed share 0.1303). p=0.13 approximates the probability of creeping over the stop line in the last 5s of red. t_before_green=5s matches the observation window."
  },
  {
   "rule_type": "queue_space_seeking",
   "applies_to": [
    "moto_seeker"
   ],
   "params": {
    "q": 35.0,
    "t_g_s": 7.0,
    "est_noise": 0.1,
    "p_wrong_lane": 0.25,
    "p_right_lane": 0.0,
    "p_sidewalk": 0.0,
    "v_creep": 3.0,
    "merge_zone_m": 15.0
   },
   "rationale": "Targets M8/moto wrong-lane share (obs 0.2131) and M9a (queue blocking). q=35m triggers seeking at moderate queues. t_g_s=7s estimates green clearance. p_wrong_lane=0.25 sets a higher probability to match the observed lateral encroachment, compensating for the specific trigger conditions of the proxy net."
  },
  {
   "rule_type": "uturn_bypass",
   "applies_to": [
    "moto_saval",
    "moto_seeker",
    "moto_violator_saval"
   ],
   "params": {
    "p": 0.8,
    "t_wait": 2.0
   },
   "rationale": "Field observation: most motorcycles pass a standing U-turner; p=0.8 (80% probability) and t_wait=2s reflects quick lateral filtering."
  },
  {
   "rule_type": "uturn_bypass",
   "applies_to": [
    "car_saval",
    "car_seeker"
   ],
   "params": {
    "p": 0.1,
    "t_wait": 2.0
   },
   "rationale": "Field observation: cars rarely bypass U-turners; p=0.1 (10% probability) matches conservative car behaviour."
  }
 ]
}

